import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs,[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]))
tr=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def nominal(r):
 return sum(slot[j][i] for i,j in enumerate(r))+sum(tr[a][jobs.index(b)] for a,b in zip(r,r[1:]))
def incident(r,s):
 p={j:r.index(j)+1 for j in jobs}
 if p['A']>p['D']: return None
 if s=='rain':
  if p['E']==2 or p['D']==5:return None
  return nominal(r)+6*max(0,p['A']-2)
 if s=='road':
  if p['B']==5 or p['D']==1:return None
  return nominal(r)+8*max(0,p['C']-3)
 if p['D']==4 or p['C']==1:return None
 return nominal(r)+5*max(0,p['E']-1)
def solve():
 results=[]
 for tup in itertools.permutations(jobs):
  r=''.join(tup)
  if r.index('A')>r.index('D'):continue
  neighbors=[(r,0)]
  for i,j in itertools.combinations(range(5),2):
   q=list(r);q[i],q[j]=q[j],q[i]
   neighbors.append((''.join(q),4))
  repairs={};costs={}
  for s in ['rain','road','lift']:
   opts=[(incident(q,s)+fee,q) for q,fee in neighbors if incident(q,s) is not None]
   if not opts:break
   costs[s],repairs[s]=min(opts)
  if len(costs)==3:results.append((nominal(r)+max(costs.values()),r,repairs,costs))
 results.sort()
 best=results[0]
 return {'roster':best[1],'score':best[0],'repairs':best[2],'repair_costs':best[3],'feasible_count':len(results),'next_score':min(x[0] for x in results if x[0]>best[0])}
answer=solve()
# Independent verifier: enumerate all final permutations and use Hamming distance 0 or 2.
valid=[r for r in itertools.permutations(jobs) if r.index('A')<r.index('D')]
alt=[]
for pub in valid:
 costs=[]
 for s in ['rain','road','lift']:
  candidates=[]
  for final in valid:
   d=sum(a!=b for a,b in zip(pub,final))
   if d not in (0,2):continue
   value=incident(final,s)
   if value is not None:candidates.append(value+(4 if d else 0))
  if not candidates:break
  costs.append(min(candidates))
 if len(costs)==3:alt.append(nominal(pub)+max(costs))
assert answer['score']==min(alt)
assert answer['feasible_count']==len(alt)
assert answer['next_score']==sorted(set(alt))[1]
for s,r in answer['repairs'].items():
 d=sum(a!=b for a,b in zip(answer['roster'],r))
 assert d in (0,2)
 assert incident(r,s)+(4 if d else 0)==answer['repair_costs'][s]
print(json.dumps(answer))
print('Verified with independent all-pairs neighborhood enumeration; published nominal:',nominal(answer['roster']))

